package firewall

import (
	"strings"
	"testing"

	"github.com/simpledcp/openaccessbridge/internal/model"
)

// TestConfigFromInputs_DerivesApplicableRuleset proves stored configuration turns
// into a ruleset that Generate accepts (§9.1: "The real ruleset is profile-driven
// and generated by the firewall manager") — the derivation the install/boot apply
// path needs, without this package touching the SQLite store.
func TestConfigFromInputs_DerivesApplicableRuleset(t *testing.T) {
	in := Inputs{
		Profile:      model.ProfileBoothDiagnostic,
		TheaterIface: "eth0",
		ClientIface:  "wlan0",
		Auditorium: model.AuditoriumProfile{
			AuditoriumID:   "screen-3",
			CinemaServerIP: "10.10.20.15",
			ACSPPort:       4170,
			ACSPInitiation: model.ACSInitiated,
		},
	}
	cfg := ConfigFromInputs(in)
	script, err := Generate(cfg)
	if err != nil {
		t.Fatalf("Generate from derived config: %v", err)
	}
	out := chainBody(t, script, "output")
	if !containsRule(out, `oif "eth0" ip daddr 10.10.20.15 tcp dport 4170 accept`) {
		t.Fatalf("derived ruleset missing the theater rule:\n%s", strings.Join(out, "\n"))
	}
	if !containsRule(chainBody(t, script, "input"), `iif "wlan0" tcp dport { 80, 443 } accept`) {
		t.Fatalf("derived ruleset missing the default patron web ports:\n%s", script)
	}
	if !containsRule(chainBody(t, script, "input"), `udp dport 10000-20000`) {
		t.Fatalf("derived ruleset missing the default WebRTC range:\n%s", script)
	}
}

// TestConfigFromInputs_Defaults pins the recorded defaults (D6 Variant A, D7 port
// 4170) and the fall-through of LocalACSPPort, so an auditorium profile saved
// before those fields existed still yields a valid ruleset.
func TestConfigFromInputs_Defaults(t *testing.T) {
	cases := []struct {
		name           string
		aud            model.AuditoriumProfile
		localPort      int
		wantInitiation model.ACSPInitiation
		wantACSPPort   int
		wantLocalPort  int
	}{
		{
			name:           "empty profile falls back to D6/D7",
			aud:            model.AuditoriumProfile{CinemaServerIP: "10.0.0.5"},
			wantInitiation: model.ACSInitiated, wantACSPPort: DefaultACSPPort, wantLocalPort: DefaultACSPPort,
		},
		{
			name: "explicit variant B keeps its ports",
			aud: model.AuditoriumProfile{
				CinemaServerIP: "10.0.0.5", ACSPPort: 5000, ACSPInitiation: model.ServerInitiated,
			},
			localPort:      6000,
			wantInitiation: model.ServerInitiated, wantACSPPort: 5000, wantLocalPort: 6000,
		},
		{
			name: "variant B without a local port reuses the ACSP port",
			aud: model.AuditoriumProfile{
				CinemaServerIP: "10.0.0.5", ACSPPort: 5000, ACSPInitiation: model.ServerInitiated,
			},
			wantInitiation: model.ServerInitiated, wantACSPPort: 5000, wantLocalPort: 5000,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			cfg := ConfigFromInputs(Inputs{
				Profile: model.ProfilePatronFacing, TheaterIface: "eth0", ClientIface: "wlan0",
				Auditorium: tc.aud, LocalACSPPort: tc.localPort,
			})
			if cfg.Initiation != tc.wantInitiation {
				t.Errorf("Initiation = %q, want %q", cfg.Initiation, tc.wantInitiation)
			}
			if cfg.ACSPPort != tc.wantACSPPort {
				t.Errorf("ACSPPort = %d, want %d", cfg.ACSPPort, tc.wantACSPPort)
			}
			if cfg.LocalACSPPort != tc.wantLocalPort {
				t.Errorf("LocalACSPPort = %d, want %d", cfg.LocalACSPPort, tc.wantLocalPort)
			}
			if _, err := Generate(cfg); err != nil {
				t.Errorf("derived config must be generatable: %v", err)
			}
		})
	}
}

// TestConfigFromInputs_MultiIPStoredField proves a multi-host booth is expressible
// through the existing scalar setting, so the allowlist shape does not wait on a
// schema change.
func TestConfigFromInputs_MultiIPStoredField(t *testing.T) {
	cfg := ConfigFromInputs(Inputs{
		Profile: model.ProfilePatronFacing, TheaterIface: "eth0", ClientIface: "wlan0",
		Auditorium: model.AuditoriumProfile{CinemaServerIP: "10.10.20.15, 10.10.20.16"},
	})
	script, err := Generate(cfg)
	if err != nil {
		t.Fatalf("Generate: %v", err)
	}
	want := `oif "eth0" ip daddr { 10.10.20.15, 10.10.20.16 } tcp dport 4170 accept`
	if !containsRule(chainBody(t, script, "output"), want) {
		t.Fatalf("missing multi-IP theater rule %q:\n%s", want, script)
	}
}

// TestConfigFromInputs_AdminGatedByProfile: the derivation may request admin on
// the client interface, but a production profile still never emits it (§8.4).
func TestConfigFromInputs_AdminGatedByProfile(t *testing.T) {
	for _, tc := range []struct {
		profile model.FirewallProfile
		wantRow bool
	}{
		{model.ProfileLab, true},
		{model.ProfileBoothDiagnostic, true},
		{model.ProfilePatronFacing, false},
		{model.ProfileLowCostReplacement, false},
	} {
		t.Run(string(tc.profile), func(t *testing.T) {
			cfg := ConfigFromInputs(Inputs{
				Profile: tc.profile, TheaterIface: "eth0", ClientIface: "wlan0",
				Auditorium:         model.AuditoriumProfile{CinemaServerIP: "10.0.0.5"},
				AdminOnClientIface: true,
			})
			script, err := Generate(cfg)
			if err != nil {
				t.Fatalf("Generate: %v", err)
			}
			got := strings.Contains(script, "admin/setup UI")
			if got != tc.wantRow {
				t.Errorf("admin rule present = %v, want %v", got, tc.wantRow)
			}
		})
	}
}
